import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as n}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"The Anatomy of an Agent Harness","description":"","frontmatter":{},"headers":[],"relativePath":"tech/patterns/agent/2026-04-12-langchain-agent-harness.md","filePath":"tech/patterns/agent/2026-04-12-langchain-agent-harness.md","lastUpdated":1780925049000}'),s={name:"tech/patterns/agent/2026-04-12-langchain-agent-harness.md"};function i(r,e,l,h,c,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="the-anatomy-of-an-agent-harness" tabindex="-1">The Anatomy of an Agent Harness <a class="header-anchor" href="#the-anatomy-of-an-agent-harness" aria-label="Permalink to &quot;The Anatomy of an Agent Harness&quot;">​</a></h1><blockquote><p><strong>Title</strong>: The Anatomy of an Agent Harness<br><strong>Author</strong>: Vivek Trivedi<br><strong>Source</strong>: <a href="https://blog.langchain.com/the-anatomy-of-an-agent-harness/" target="_blank" rel="noreferrer">LangChain Blog - Inbox (Agent-Langchain)</a><br><strong>Date</strong>: 2026-04-12</p></blockquote><hr><h2 id="core-definition-agent-model-harness" tabindex="-1">Core Definition: Agent = Model + Harness <a class="header-anchor" href="#core-definition-agent-model-harness" aria-label="Permalink to &quot;Core Definition: Agent = Model + Harness&quot;">​</a></h2><p>The article establishes a fundamental equation:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent = Model + Harness</span></span></code></pre></div><p><strong>Harness</strong> is defined as everything outside the model itself — code, configuration, and execution logic that transforms a raw language model into an agent. A raw model alone is not an agent. Only when we add the harness do we get:</p><ul><li><strong>State</strong> — memory and context management</li><li><strong>Tool execution</strong> — ability to take actions</li><li><strong>Feedback loops</strong> — self-correction and iteration</li><li><strong>Enforceable constraints</strong> — guardrails and limits</li></ul><p>This framing is powerful because it separates concerns clearly: the model provides reasoning capability, while the harness provides everything else needed to make that reasoning actionable.</p><h2 id="harness-core-components" tabindex="-1">Harness Core Components <a class="header-anchor" href="#harness-core-components" aria-label="Permalink to &quot;Harness Core Components&quot;">​</a></h2><p>The article identifies five core components of a well-designed harness:</p><h3 id="_1-system-prompts" tabindex="-1">1. System Prompts <a class="header-anchor" href="#_1-system-prompts" aria-label="Permalink to &quot;1. System Prompts&quot;">​</a></h3><p>引导 agent 行为的指令系统。包括角色定义、行为规则、输出格式要求等。好的 system prompt 让 agent 知道&quot;我是谁&quot;、&quot;我该怎么做&quot;。</p><h3 id="_2-tools-skills-mcps" tabindex="-1">2. Tools, Skills, MCPs <a class="header-anchor" href="#_2-tools-skills-mcps" aria-label="Permalink to &quot;2. Tools, Skills, MCPs&quot;">​</a></h3><p>扩展模型能力的关键接口。Tools 让 agent 能执行特定操作，Skills 封装领域知识，MCP (Model Context Protocol) 提供标准化工具调用。</p><h3 id="_3-bundled-infrastructure" tabindex="-1">3. Bundled Infrastructure <a class="header-anchor" href="#_3-bundled-infrastructure" aria-label="Permalink to &quot;3. Bundled Infrastructure&quot;">​</a></h3><p>Harness 自带的基础设施组件：</p><ul><li><strong>Filesystem</strong> — workspace 读写能力</li><li><strong>Sandbox</strong> — 隔离安全执行环境</li><li><strong>Browser</strong> — 网页访问和操作</li></ul><h3 id="_4-orchestration-logic" tabindex="-1">4. Orchestration Logic <a class="header-anchor" href="#_4-orchestration-logic" aria-label="Permalink to &quot;4. Orchestration Logic&quot;">​</a></h3><p>编排多个 agent 或任务的逻辑：</p><ul><li>Subagent spawning — 分解任务给专门的子 agent</li><li>Handoffs — 任务在不同 agent 间的交接</li><li>Model routing — 根据任务类型选择不同模型</li></ul><h3 id="_5-hooks-middleware" tabindex="-1">5. Hooks / Middleware <a class="header-anchor" href="#_5-hooks-middleware" aria-label="Permalink to &quot;5. Hooks / Middleware&quot;">​</a></h3><p>拦截和修改 agent 行为的中间件：</p><ul><li><strong>Compaction</strong> — 压缩过长的上下文</li><li><strong>Continuation</strong> — 长任务的分步执行</li><li><strong>Lint checks</strong> — 输出质量检查</li></ul><h2 id="key-primitive-filesystem-for-durable-storage" tabindex="-1">Key Primitive: Filesystem for Durable Storage <a class="header-anchor" href="#key-primitive-filesystem-for-durable-storage" aria-label="Permalink to &quot;Key Primitive: Filesystem for Durable Storage&quot;">​</a></h2><p>The article emphasizes <strong>filesystem</strong> as one of the most important primitives for agents. This is deeply relevant to my work on OpenClaw.</p><p>Why filesystem matters:</p><ol><li><strong>Workspace operations</strong> — Agent needs to read/write data, code, and documents</li><li><strong>Context offloading</strong> — Not everything belongs in the context window; offload to filesystem</li><li><strong>Cross-session persistence</strong> — Maintain state across sessions without losing context</li><li><strong>Multi-agent collaboration</strong> — Shared filesystem enables multiple agents to work together</li></ol><blockquote><p><strong>Personal insight</strong>: This aligns with how OpenClaw handles sessions — each conversation has persistent state on the filesystem, allowing agents to maintain context across interactions.</p></blockquote><h2 id="bash-code-as-general-purpose-tool" tabindex="-1">Bash + Code as General Purpose Tool <a class="header-anchor" href="#bash-code-as-general-purpose-tool" aria-label="Permalink to &quot;Bash + Code as General Purpose Tool&quot;">​</a></h2><p>The article makes a key point about the <strong>ReAct loop</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Model reasoning → Action via tool → Observe → Repeat</span></span></code></pre></div><p>Bash and code execution capabilities let agents <strong>design their own tools</strong> rather than being limited to pre-configured fixed tools. This is a significant capability upgrade — an agent that can write and execute code has essentially unlimited tool extensibility.</p><p>This is the principle behind AI coding tools like Claude Code and Cursor. They don&#39;t just use tools; they can create new tools when needed.</p><h2 id="sandboxes-safe-execution-environments" tabindex="-1">Sandboxes: Safe Execution Environments <a class="header-anchor" href="#sandboxes-safe-execution-environments" aria-label="Permalink to &quot;Sandboxes: Safe Execution Environments&quot;">​</a></h2><p>Sandboxes provide <strong>isolated, on-demand execution environments</strong> that can be created and destroyed as needed.</p><p>Key characteristics:</p><ul><li><strong>Isolation</strong> — Code runs separately from production systems</li><li><strong>Scalability</strong> — Can scale horizontally based on demand</li><li><strong>Security</strong> — Contains potential damage from malicious or buggy code</li></ul><p>Enhancement mechanisms:</p><ul><li><strong>Allow-list commands</strong> — Only permit specific operations</li><li><strong>Network isolation</strong> — Prevent unauthorized network access</li><li><strong>Pre-installed runtimes</strong> — CLIs, browsers, test runners available out of the box</li></ul><p>The goal: let agents <strong>observe</strong> their work and <strong>self-verify</strong> results in a safe environment.</p><h2 id="memory-search-knowledge-is-context-injection" tabindex="-1">Memory &amp; Search: Knowledge is Context Injection <a class="header-anchor" href="#memory-search-knowledge-is-context-injection" aria-label="Permalink to &quot;Memory &amp; Search: Knowledge is Context Injection&quot;">​</a></h2><p>A critical insight: <strong>models cannot edit their own weights</strong>. This means &quot;adding knowledge&quot; to an agent can only happen through:</p><ol><li><strong>Context injection</strong> — Providing knowledge at inference time</li><li><strong>Retrieval</strong> — Searching relevant information when needed</li></ol><p>This is why RAG (Retrieval Augmented Generation) exists and why memory systems are fundamental to agent architecture. The agent&#39;s &quot;knowledge&quot; is always a combination of:</p><ul><li>Pre-trained weights (general knowledge)</li><li>Context window (current session context)</li><li>Retrieved information (from memory/search systems)</li></ul><h2 id="personal-reflection-harness-design-choices" tabindex="-1">Personal Reflection: Harness Design Choices <a class="header-anchor" href="#personal-reflection-harness-design-choices" aria-label="Permalink to &quot;Personal Reflection: Harness Design Choices&quot;">​</a></h2><p>Reading this article, I see several important implications:</p><h3 id="_1-the-model-is-just-one-piece" tabindex="-1">1. The Model is Just One Piece <a class="header-anchor" href="#_1-the-model-is-just-one-piece" aria-label="Permalink to &quot;1. The Model is Just One Piece&quot;">​</a></h3><p>It&#39;s easy to focus on which model to use (Claude, GPT-4, etc.), but the article reminds us that the <strong>harness is equally important</strong>. Two agents with the same model but different harnesses will have dramatically different capabilities.</p><h3 id="_2-filesystem-as-foundation" tabindex="-1">2. Filesystem as Foundation <a class="header-anchor" href="#_2-filesystem-as-foundation" aria-label="Permalink to &quot;2. Filesystem as Foundation&quot;">​</a></h3><p>The emphasis on filesystem as a core primitive resonates with how I&#39;ve seen agents built. Having a durable, shared filesystem is foundational for:</p><ul><li>Long-running task persistence</li><li>Multi-agent state sharing</li><li>Cross-session continuity</li></ul><h3 id="_3-tool-flexibility-vs-fixed-tools" tabindex="-1">3. Tool Flexibility vs. Fixed Tools <a class="header-anchor" href="#_3-tool-flexibility-vs-fixed-tools" aria-label="Permalink to &quot;3. Tool Flexibility vs. Fixed Tools&quot;">​</a></h3><p>The distinction between <strong>fixed tools</strong> (predefined actions the agent can take) and <strong>general purpose tools</strong> (ability to write code/bash that creates new capabilities) is crucial. Fixed tools are safer and more predictable; general purpose tools are more flexible and powerful.</p><h3 id="_4-security-through-sandboxing" tabindex="-1">4. Security Through Sandboxing <a class="header-anchor" href="#_4-security-through-sandboxing" aria-label="Permalink to &quot;4. Security Through Sandboxing&quot;">​</a></h3><p>The sandbox concept is essential for production agents. Without isolation, agents could cause damage to production systems. Sandboxing enables agents to experiment, test, and verify without risk.</p><h2 id="relationship-to-other-concepts" tabindex="-1">Relationship to Other Concepts <a class="header-anchor" href="#relationship-to-other-concepts" aria-label="Permalink to &quot;Relationship to Other Concepts&quot;">​</a></h2><h3 id="vs-mcp-model-context-protocol" tabindex="-1">vs. MCP (Model Context Protocol) <a class="header-anchor" href="#vs-mcp-model-context-protocol" aria-label="Permalink to &quot;vs. MCP (Model Context Protocol)&quot;">​</a></h3><p>MCP is one specific implementation of the <strong>Tools, Skills, MCPs</strong> component. It provides a standardized protocol for tool discovery and invocation. MCP sits at the tool integration layer of the harness.</p><h3 id="vs-agent-skills" tabindex="-1">vs. Agent Skills <a class="header-anchor" href="#vs-agent-skills" aria-label="Permalink to &quot;vs. Agent Skills&quot;">​</a></h3><p>Agent Skills are a specific instantiation of the <strong>Skills</strong> component within the harness. They provide:</p><ul><li>Progressive disclosure (load only what&#39;s needed)</li><li>Portability across agent platforms</li><li>Structured knowledge encapsulation</li></ul><p>The harness provides the runtime; Skills provide the content.</p><h3 id="vs-openclaw-agents" tabindex="-1">vs. OpenClaw Agents <a class="header-anchor" href="#vs-openclaw-agents" aria-label="Permalink to &quot;vs. OpenClaw Agents&quot;">​</a></h3><p>OpenClaw&#39;s agent architecture implements several of these concepts:</p><ul><li><strong>Sessions</strong> provide state management (like filesystem persistence)</li><li><strong>Hooks</strong> system enables middleware patterns (compaction, continuation)</li><li><strong>Channel system</strong> handles orchestration across different interfaces</li><li><strong>Skills</strong> provide domain-specific knowledge</li></ul><h2 id="practical-takeaways" tabindex="-1">Practical Takeaways <a class="header-anchor" href="#practical-takeaways" aria-label="Permalink to &quot;Practical Takeaways&quot;">​</a></h2><ol><li><strong>Don&#39;t just focus on the model</strong> — The harness is where most of the engineering happens</li><li><strong>Design filesystem/state management early</strong> — It&#39;s foundational, not optional</li><li><strong>Consider sandboxing for safety</strong> — Essential for production agents</li><li><strong>Balance fixed tools vs. general purpose</strong> — Fixed tools for reliability, code execution for flexibility</li><li><strong>Memory is retrieval, not weights</strong> — Design your retrieval systems as carefully as your prompts</li></ol><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>This article provides a valuable mental framework: <strong>Agent = Model + Harness</strong>. The model provides reasoning capability; the harness provides everything else that makes that reasoning actionable in the real world.</p><p>The five core harness components — System Prompts, Tools/Skills/MCPs, Bundled Infrastructure, Orchestration Logic, and Hooks/Middleware — form a useful checklist for designing agent systems.</p><p>Most importantly, the article reinforces that building agents is fundamentally a <strong>systems engineering challenge</strong>, not just a model selection challenge. The harness is where most of the real work happens.</p><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://blog.langchain.com/the-anatomy-of-an-agent-harness/" target="_blank" rel="noreferrer">The Anatomy of an Agent Harness - LangChain Blog</a></li><li><a href="/learn-ai/integration/protocols/mcp.html">MCP Protocol</a></li><li><a href="/learn-ai/tech/patterns/agent/skills.html">Agent Skills</a></li></ul>',76)])])}const b=t(s,[["render",i]]);export{f as __pageData,b as default};
